thread := cli.Int(
    "thread",
    cli.setDefault(5),
    cli.setRequired(true),
    cli.setVerboseName("线程数"),
    cli.setHelp("最大线程"),
    cli.setCliGroup("速率设置"),
)

isApiTest = cli.Bool(
    "is_api_test", 
    cli.setHelp("是否开启API批量发包测试"), 
    cli.setVerboseName("接口请求测试"), 
    cli.setCliGroup("接口请求测试"), 
)

expectedUrl = cli.String(
    "expected_url", 
    cli.setDefault("weixin.qq.com,www.w3.org,map.qq.com,restapi.amap.com"), 
    cli.setVerboseName("URL黑名单"), 
    cli.setHelp("不进行拼接的url将其进行接口拼接并发送网络请求"), 
    cli.setCliGroup("接口请求测试"), 
