expectedStatuscode = cli.String(
    "status_code", 
    cli.setDefault("404"), 
    cli.setVerboseName("状态码黑名单"), 
    cli.setHelp("排除接口测试状态码不符合的接口，多个状态码以逗号隔开"), 
    cli.setCliGroup("接口请求测试"), 
