/* ================================= 缓存清理功能 =============================================== */
# 删除缓存操作
removeWxFile = func(appletPath, message) {
    file.Walk(
        appletPath,
        func(info) {
            if file.IsDir(info.Path) {
                os.RemoveAll(info.Path)~

            }
            return true
        }
    )
    println(f"清除${message}成功！")
}

/* ================================= 文件扫描功能 =============================================== */
// GetWxapkgFiles 扫描微信小程序目录，返回子目录名与 .wxapkg 文件路径列表
// rootPath: 微信小程序根目录（如 `C:\Users\...\Applet\packages`）  
func GetWxapkgFiles(packagesPath) {
    var filePath = make([]string)
    for d in file.Dir(packagesPath) {
        subPath := file.Join(packagesPath, d.Name)
        for f in file.ReadFileInfoInDirectory(subPath)~ {
            // println(f.Path)
            if file.IsFile(f.Path) {
                // println(f.Path)
                filePath = append(filePath, f.Path)
            }
        }
    }

    return filePath
}


func getAppID(filePaths) {
    for f in filePaths {
        // 检查文件名是否是 '__APP__.wxapkg'
        if file.GetBase(f) == "__APP__.wxapkg" {
            appID = re.Find(f, `\bwx[a-f0-9]{16}\b`)
            yakit.Info("✅成功获取到 appID：%s", appID)
            return appID  // 找到后立即返回对应的目录名（appID）
        }
    }

}


# 辅助函数，使用大端编码读取字节数组内容并转化为数字
# 参数 b: 要转换的字节数组
# 返回值: 根据字节长度返回对应的无符号整数
func ReadUnit(b){
    byteLen = len(b)  # 获取字节数组长度
    switch byteLen {  # 根据长度进行不同处理
        case 1:  # 1字节直接转换为int
            return int(byte)
        case 2:  # 2字节使用大端序转换为uint16
            return uint16(b[1]) | ( uint16(b[0])<<8)
        case 4:  # 4字节使用大端序转换为uint32
            return uint32(b[3]) | ( uint32(b[2])<<8) | ( uint32(b[1])<<16) | (uint32(b[0])<<24)
    }
}

# 解包函数，用于解压wxapkg文件
# 参数 wxapkgPath: wxapkg文件路径
# 参数 outputPath: 输出目录
# 参数 thread: 使用的线程数
# 返回值: 解压的文件数量
unpack = func(wxapkgPath, outputPath , thread) {
    wxapkgFile = file.GetBase(wxapkgPath)  # 获取文件名(不含路径)
    f = file.Open(wxapkgPath)~  # 打开wxapkg文件
    decryptedData = file.ReadAll(f)~  # 读取全部文件内容

    # 解析文件头部信息
    firstMark = decryptedData[0]  # 第一个标识字节(应为0xBE)
    unknownInfo = decryptedData[1:5]  # 未使用的4字节信息
    infoListLength = decryptedData[5:9]  # 信息列表长度
    dataLength = decryptedData[9:13]  # 数据段长度
    lastMark = decryptedData[13]  # 最后一个标识字节(应为0xED)

    # 检查文件标识是否正确(头尾标记)
    if !firstMark == 0xbe || !lastMark == 0xed {
        yakit.Error("❌解包失败，%s 文件不是可用的 wxapkg 文件。", wxapkgFile)
        return 0
    }

    # 读取文件数量并从文件列表中解析每个文件的元信息
    fileCount = ReadUnit(decryptedData[14:18])  # 获取文件中包含的资源文件数量
    fileList = []  # 用于存储所有文件的元信息
    idx = 18  # 当前读取位置(跳过头部信息后)

    # 循环解析每个文件的元信息(文件名、偏移量、大小等)
    for i = 0; i<fileCount; i++ {
        # 读取文件名长度(4字节)
        nameLenByte = decryptedData[idx:idx+4]
        idx += 4
        nameLen = ReadUnit(nameLenByte)  # 转换为实际的长度数值

        # 安全限制：防止文件名长度异常大导致内存问题
        if nameLen  > 10485760 {
            yakit.Error("❌解包失败，%s 文件不是可用的 wxapkg 文件。", wxapkgFile)
            return 0
        }

        # 读取文件名数据
        dataNameByte = decryptedData[idx:idx+nameLen]
        idx += nameLen

        # 读取文件偏移量和大小(各4字节)
        offsetByte = decryptedData[idx:idx+4]
        idx += 4
        sizeByte = decryptedData[idx:idx+4]
        idx += 4

        # 将文件元信息存入列表
        fileList = append(
            fileList,
            {
                "nameLen": nameLenByte,
                "name": dataNameByte,
                "offset": offsetByte,
                "size": sizeByte
            }
        )
    }

    # 使用多线程保存文件
    chFiles = make(chan var)  # 创建通道用于文件数据传递
    wg = sync.NewWaitGroup()  # 创建等待组
    wg.Add(1)  # 添加生产者计数

    # 启动生产者协程：将文件元信息放入通道
    go func() {
        defer wg.Done()  # 完成时通知等待组
        for _,d = range fileList{
            chFiles<-d  # 发送文件数据到通道
        }
        close(chFiles)  # 关闭通道
    }()

    # 启动消费者协程(多个)：从通道取出数据并写入文件
    wg.Add(thread)  # 添加消费者计数
    locker = sync.NewMutex()  # 创建互斥锁
    count = 0  # 进度计数器

    # 启动多个工作协程
    for i=0 ; i<thread; i++ {
        go func() {
            defer wg.Done()
            # 从通道中获取文件数据并处理
            for d := range chFiles {
                # 构造输出文件完整路径
                d.name = []byte(str.PathJoin(outputPath, string(d.name)))
                outputFilePath = string(d.name)
                dir = file.GetDirPath(outputFilePath)

                # 创建必要的目录结构
                err:= file.MkdirAll(dir)
                if err != nil{
                    yakit.Error("⚠️解包错误，创建文件夹失败：%v", err)
                }

                # 读取文件实际数据并保存
                offset = ReadUnit(d.offset)  # 获取文件在wxapkg中的偏移量
                size = ReadUnit(d.size)      # 获取文件大小
                data = decryptedData[offset:offset+size]  # 提取文件数据
                err = file.Save(outputFilePath, data)  # 保存到文件
                if err != nil {
                    yakit.Error("⚠️解包错误，写入文件失败：%v", err)
                }

                # 更新进度
                locker.Lock()  # 加锁避免多线程冲突
                count++
                yakit.SetProgress( count/fileCount)  # 更新进度条
                locker.Unlock()  # 释放锁
            }
        }()
    }
    wg.Wait()  # 等待所有协程完成

    return fileCount  # 返回解压的文件总数
}


/* ================================= 小程序信息查询模块 =============================================== */
# 利用wxid查询小程序相关信息
query = func(wxid) {
    // 1. 构建HTTP POST请求数据
    // 目标API: kainy.cn 的小程序信息查询接口
    // 请求体为JSON格式，包含要查询的小程序ID
    queryData = f`POST /api/weapp/info/ HTTP/1.1
Host: kainy.cn
Content-Type: application/json;charset=utf-8
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/83.0.4103.116 Safari/537.36

{"appid":"${wxid}"}`

    // 2. 发送HTTP请求
    // 使用HTTPEx方法发送请求，设置10秒超时
    rsp, req, err = poc.HTTPEx(queryData, poc.timeout(10))
    if err != nil {
        // 请求失败处理：记录错误日志并返回
        yakit.Error("查询wxid：%v失败: %v", wxid, err)
        return nil
    }

    // 3. 验证HTTP响应状态码
    // 仅当状态码为200时继续处理
    if rsp.GetStatusCode() != 200 {
        // 非200状态码处理：记录错误日志并返回
        yakit.Error("API响应异常: HTTP %v", rsp.GetStatusCode())
        return nil
    }

    // 4. 解析JSON响应体
    // 将响应正文转换为JSON对象
    jsonRaw = json.loads(rsp.GetBody())

    // 5. 校验API返回的业务状态码
    // 当code字段不为0时表示小程序未收录
    codeValue = json.Find(jsonRaw, "$.code")
    if codeValue != 0 {
        // 未收录处理：记录警告、更新状态卡并显示基本信息
        yakit.Warn("小程序 %v 未收录: %v", wxid, json.Find(jsonRaw, "$.message"))
        yakit.StatusCard("小程序信息", "未知小程序", wxid)
        
        // 创建表格展示可用数据
        yakit.EnableTable("小程序信息", ["Key", "Value"])
        for k, v in jsonRaw.data {
            // 将每个键值对添加到表格
            yakit.TableData("小程序信息", {"Key": k, "Value": v})
        }
        
        // 返回有限的数据对象
        return {
            "nickName": jsonRaw.data.nickName,
            "userName": jsonRaw.data.userName,
            "description": jsonRaw.data.description,
            "avatar": jsonRaw.data.avatar,
            "principalName": jsonRaw.data.principalName, 
            "appid": jsonRaw.data.appid
        }
    }

    // 6. 成功路径处理
    // 更新状态卡显示小程序名称和ID
    yakit.StatusCard("小程序信息", string(jsonRaw.data.nickname), jsonRaw.data.appid)
    
    // 创建表格展示完整数据
    yakit.EnableTable("小程序信息", ["Key", "Value"])
    for k, v in jsonRaw.data {
        // 将每个键值对添加到表格
        yakit.TableData("小程序信息", {"Key": k, "Value": v})
    }

    // 返回完整的数据对象
    return {
        "nickName": jsonRaw.data.nickName,
        "userName": jsonRaw.data.userName,
        "description": jsonRaw.data.description,
        "avatar": jsonRaw.data.avatar,
        "principalName": jsonRaw.data.principalName, 
        "appid": jsonRaw.data.appid
    }
}


/* ================================= URL过滤助手 =============================================== */
#辅助函数，判断url是否在黑名单里面
func IsInExpectedUrl(url) {
    expectedUrlSlice = str.Split(expectedUrl, ",")
    for u in expectedUrlSlice {
        if str.Contains(url, u){
            return false
        }
    }
    return true
}

/* ================================= 状态码过滤助手 =============================================== */
func IsInExpectedStatuscode(code) {
    expectedCode = str.Split(expectedStatuscode, ",")
    for c in expectedCode {
        if string(code) == expectedCode {
            return true
        }
    }
    return false
}

/* ================================= 信息泄露检测核心 =============================================== */
infoLeakDetect = func(wxapkgInfo, outputPath, wxid) {
    nickName = ""
    if wxapkgInfo.nickName != "" {
        nickName = wxapkgInfo.nickName
    } else {
        nickName = wxid
    }
    apiTableName = f`URL接口信息`
    yakit.EnableTable(apiTableName, ["文件位置","泄露内容","泄露类型","状态码"])

    sensitiveName = f`敏感信息泄露`
    yakit.EnableTable(sensitiveName, ["文件位置","泄露内容","泄露类型"])

    wg = sync.NewWaitGroup()
    locker =sync.NewMutex
    matchMap = sync.NewMap()
    matchChan := make(chan []string)
    go func() {
        wg.Wait()
        close(matchChan)
    }()
    wg.Add(1)
    go matchFilePath(outputPath, matchChan, matchMap, wg)
    data = make(map[string]var)
    for c := range matchChan {
        filePath = c[0]
        url = c[1]
        typ = c[2]
        statusCode = 0
        data["文件位置"] = filePath
        data["泄露内容"] = url
        data["泄露类型"] = typ
        if typ == "接口泄露" {
            if isApiTest&&str.IsHttpURL(url)&& !IsInExpectedUrl(url) {
                rsp, req, err = poc.Get(url, poc.replaceRandomUserAgent())
                if err == nil {
                    statusCode=poc.GetStatusCodeFromResponse(rsp.BareResponse)
                    if IsInExpectedStatuscode(statusCode) {
                        continue
                    }
                }
            }
            data["状态码"] = statusCode
            yakit.TableData(apiTableName, data)
        } else {
            yakit.TableData(sensitiveName, data)
        }
    }
}


/* ================================= 图像文件检测助手 =============================================== */
# 辅助函数，判断文件名或者接口名是否为图片
func IsImg(name) {
    if str.Contains(name, ".jpg") || str.Contains(name, ".png") || str.Contains(name, ".jpeg") || str.Contains(name, ".gif") || str.Contains(name, ".svg") {
        return true
    }

    return false
}

/* ================================= 文件内容扫描器 =============================================== */
#遍历各个文件内容，并使用正则匹配
func matchFilePath(dir, matchChan, matchMap, wg) {
    defer wg.Done()

    files = file.Dir(dir)
    for f in files {
        if file.IsDir(f.Path) {
            wg.Add(1)
            go matchFilePath(f.Path, matchChan, matchMap, wg)
        } else {
            if IsImg(f.Name){
                continue
            }

            f2 = file.Open(f.Path)~
            defer f2.Close()


            content = f2.ReadString()~
            results = pattern.FindAllStringSubmatch(content, -1)
            for res in results {
                if IsImg(res[1]){
                    continue
                }
                ret = res[1]
               _, ok = matchMap.Load(ret)
               if ok {
                continue
               }
                matchChan <- [f.Path,res[1],"接口泄露"]
                matchMap.Store(ret,true)
            }

            if isSensitive{
                for typ,p := range sensitiveMap{
                    results = p.FindAllString(content, -1)
                    for res in results{
                        matchChan <- [f.Path,res,typ]
                    }
                }
            }
        }
        
    }
    
}


/* ================================= 主监控循环 =============================================== */
func main(appletPath, thread) {
    // 验证目标目录
    if !file.IsDir(appletPath) {
        yakit.Error("路径 [%s] 不存在或不是目录，请检查微信小程序存储位置", appletPath)
    }

    yakit.Info("微信小程序自动化渗透监控插件启动.............")
    yakit.Info("请在微信中操作打开目标小程序（将自动捕获文件）")

    // 超时控制（最长5分钟）
    startTime = time.Now()
    timeout = 300

    packagePath = str.PathJoin(appletPath, "packages")
    removeWxFile(packagePath, "小程序缓存")  // 清除小程序缓存
    for {
        // ===== 1. 超时检查 =====
        if time.Now().Sub(startTime).Seconds() > timeout {
            yakit.Warn("监控超时（5分钟），自动停止")
            break
        }

        // 打印路径调试
        yakit.Info(f"🔍搜索 ${packagePath} 及子路径搜索 wxapkg 文件。")
        time.sleep(8)

        // 检查是否为空目录（重要）
        if len(file.ReadDirInfoInDirectory(packagePath)~) == 0 {
            yakit.Warn("错误：目录为空 - %s", packagePath)
            time.sleep(2)
            continue
        }

        // 扫描 wxapkg 文件
        wxapkgPath = GetWxapkgFiles(packagePath)
        if len(wxapkgPath) == 0 {
            yakit.Warn("⚠️未检测到 wxapkg 文件，可能是网络问题导致未下载，请重试")
            continue
        }
        time.sleep(2)

        appID = getAppID(wxapkgPath)

        // 创建小程序反编译输出路径
        TempDir = yakit.GetHomeTempDir()
        outputTempPath = str.PathJoin(TempDir, appID)
        if file.IsExisted(outputTempPath) {
            removeWxFile(outputTempPath, "小程序解包缓存")
        } else {
            file.Mkdir(outputTempPath)
            println("小程序反编译输出路径创建成功：", outputTempPath)
        }

        // 执行小程序反编译
        yakit.Info("开始反编译小程序文件 ⬆️⬆️⬆️")
        for f in wxapkgPath {
            Path = re.Find(f, `\bwx[a-f0-9]{16}\b`)
            subPath = str.PathJoin(outputTempPath, Path)
            if file.IsDir(subPath) {
                file.Mkdir(subPath)
            }

            fileCount = unpack(f, outputTempPath, thread)
        }
        if len(file.ReadFileInfoInDirectory(outputTempPath)~) != 0 {
            yakit.File(outputTempPath, "反编译路径")
        }

        // 获取小程序的相关信息
        wxapkgInfo = query(appID)
        infoLeakDetect(wxapkgInfo, outputTempPath, appID)
        break
    }

    return 0
}


/* ================================= 路径预处理与设置 =============================================== */
// 微信小程序根路径
appletPath = wxFile
if os.Getenv("OS") == "Windows_NT" {
    user = os.GetHomeDir()
    appletPath = str.PathJoin(user, "\\AppData\\Roaming\\Tencent\\xwechat\\radium\\Applet")
}


/* ================================= 启动插件入口 =============================================== */
main(appletPath, thread)
